import json
def transform(grid, protect_nonzero=False, later_col_wins=True):
    h=len(grid); w=len(grid[0])
    # find diamonds: center cell with 3 arms
    dias=[]; zeros=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==3: continue
            arms=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
            if all(0<=a[0]<h and 0<=a[1]<w and grid[a[0]][a[1]]==3 for a in arms):
                (zeros if v==0 else dias).append((r,c,v))
    brow={r for r,c,v in zeros}; bcol={c for r,c,v in zeros}
    out=[row[:] for row in grid]
    def paint(cells,col):
        for r,c in cells:
            if r in brow or c in bcol: continue
            if grid[r][c]==3: continue
            if protect_nonzero and grid[r][c]!=0: continue
            out[r][c]=col
    for r,c,v in dias: paint([(r,cc) for cc in range(w)],v)
    cols={}
    for r,c,v in dias: cols.setdefault(c,[]).append(v)
    for c,vs in cols.items():
        v = vs[-1] if later_col_wins else vs[0]
        paint([(rr,c) for rr in range(h)],v)
    return out

