def transform(grid):
    h=len(grid); w=len(grid[0])
    dias=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v==3: continue
            arms=[(r-1,c),(r+1,c),(r,c-1),(r,c+1)]
            if all(0<=a[0]<h and 0<=a[1]<w and grid[a[0]][a[1]]==3 for a in arms):
                dias.append((r,c,v))
    zero_cols={c for r,c,v in dias if v==0}
    out=[row[:] for row in grid]
    def ray(r,c,dr,dc,col):
        rr,cc=r,c
        while True:
            rr+=dr; cc+=dc
            if not(0<=rr<h and 0<=cc<w): return
            if grid[rr][cc]==3:
                if abs(rr-r)+abs(cc-c)==1: continue  # own arm
                return
            if dc!=0 and cc in zero_cols: continue  # skip zero column, don't paint
            out[rr][cc]=col
    for r,c,v in dias:
        if v: 
            ray(r,c,0,1,v); ray(r,c,0,-1,v)
    for r,c,v in dias:
        if v:
            ray(r,c,1,0,v); ray(r,c,-1,0,v)
    return out

